export function isSlackImChannel(channelId) {
    return channelId.startsWith("D");
}
/** True when every message in this channel belongs to one session. */
export function slackDmIsOneSession(channelId, dm) {
    return dm === "whole-dm" && isSlackImChannel(channelId);
}
export function slackThreadKey(channelId, threadTs, dm) {
    return slackDmIsOneSession(channelId, dm) ? channelId : `${channelId}:${threadTs}`;
}
